/* Independent certified replay for the finite Weil matrix.
   Pole: direct integral, not source closed formula (4.2).
   Archimedean: independent alpha/beta/gamma decomposition (4.12)--(4.14),
   with the duplicated c(L) typo in printed (4.14) corrected to agree with
   the defining distribution (3.15) and formula (4.4).
   Prime powers: factor every integer independently. */
#define _POSIX_C_SOURCE 200809L
#include <flint/flint.h>
#include <flint/arb.h>
#include <flint/arb_mat.h>
#include <flint/acb.h>
#include <flint/acb_calc.h>
#include <flint/acb_hypgeom.h>
#include <flint/fmpq.h>
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

enum kind { POLE_DIRECT, ALPHA_INT, BETA_INT, GAMMA_INT };
typedef struct { enum kind kind; slong n,m; arb_t L,pi; } param_t;

static int parse_decimal(fmpq_t q,const char *s){size_t len=strlen(s),frac=0,dots=0,j=0;char *d=flint_malloc(len+2);if(!len){flint_free(d);return 0;}for(size_t i=0;i<len;i++){if(s[i]=='.'){if(++dots>1){flint_free(d);return 0;}frac=len-i-1;}else if(isdigit((unsigned char)s[i])||(i==0&&(s[i]=='+'||s[i]=='-')))d[j++]=s[i];else{flint_free(d);return 0;}}d[j]='\0';fmpz_t num,den,ten;fmpz_init(num);fmpz_init(den);fmpz_init_set_ui(ten,10);if(fmpz_set_str(num,d,10)!=0){flint_free(d);return 0;}fmpz_pow_ui(den,ten,frac);fmpq_set_fmpz_frac(q,num,den);fmpq_canonicalise(q);fmpz_clear(num);fmpz_clear(den);fmpz_clear(ten);flint_free(d);return 1;}
static int isprime(ulong n){if(n<2)return 0;if(n%2==0)return n==2;for(ulong d=3;d<=n/d;d+=2)if(n%d==0)return 0;return 1;}
static int ppbase(ulong n,ulong *p){for(ulong d=2;d<=n;d++)if(isprime(d)&&n%d==0){ulong t=n;while(t%d==0)t/=d;if(t==1){*p=d;return 1;}return 0;}return 0;}
static void setreal(acb_t z,const arb_t x){arb_set(acb_realref(z),x);arb_zero(acb_imagref(z));}

static void omega(acb_t out,slong n,slong m,const acb_t x,const acb_t L,const acb_t pi,slong prec){acb_t a,b,t;acb_init(a);acb_init(b);acb_init(t);if(n==m){acb_div(a,x,L,prec);acb_neg(a,a);acb_add_ui(a,a,1,prec);acb_mul(b,pi,x,prec);acb_mul_si(b,b,2*n,prec);acb_div(b,b,L,prec);acb_cos(b,b,prec);acb_mul(out,a,b,prec);acb_mul_2exp_si(out,out,1);}else{acb_mul(a,pi,x,prec);acb_mul_si(a,a,2*m,prec);acb_div(a,a,L,prec);acb_sin(a,a,prec);acb_mul(b,pi,x,prec);acb_mul_si(b,b,2*n,prec);acb_div(b,b,L,prec);acb_sin(b,b,prec);acb_sub(a,a,b,prec);acb_mul_si(t,pi,n-m,prec);acb_div(out,a,t,prec);}acb_clear(a);acb_clear(b);acb_clear(t);}

static int integrand(acb_ptr out,const acb_t x,void *vp,slong order,slong prec){param_t *p=(param_t*)vp;if(order>1)return 1;acb_t L,pi,a,ax,ix,den,eh,emh,tmp,tmp2,one,two;acb_init(L);acb_init(pi);acb_init(a);acb_init(ax);acb_init(ix);acb_init(den);acb_init(eh);acb_init(emh);acb_init(tmp);acb_init(tmp2);acb_init(one);acb_init(two);setreal(L,p->L);setreal(pi,p->pi);acb_one(one);acb_set_ui(two,2);acb_mul_2exp_si(tmp,x,-1);acb_exp(eh,tmp,prec);acb_neg(tmp,tmp);acb_exp(emh,tmp,prec);acb_mul(a,pi,two,prec);acb_mul_si(a,a,p->n,prec);acb_div(a,a,L,prec);acb_mul(ax,a,x,prec);acb_mul_onei(ix,x);acb_sinc(den,ix,prec);
 if(p->kind==POLE_DIRECT){omega(out,p->n,p->m,x,L,pi,prec);acb_add(tmp,eh,emh,prec);acb_mul(out,out,tmp,prec);}
 else if(p->kind==ALPHA_INT){acb_sinc(tmp,ax,prec);acb_mul(tmp,tmp,a,prec);acb_mul(tmp,tmp,eh,prec);acb_mul_2exp_si(tmp,tmp,-1);acb_div(out,tmp,den,prec);}
 else if(p->kind==BETA_INT){acb_cos(tmp,ax,prec);acb_mul(tmp,tmp,eh,prec);acb_mul_2exp_si(tmp,tmp,-1);acb_div(out,tmp,den,prec);}
 else {acb_mul_2exp_si(tmp,x,-1);acb_hypgeom_1f1(tmp2,one,two,tmp,0,prec);acb_cos(tmp,ax,prec);acb_mul(tmp2,tmp2,tmp,prec);acb_mul_2exp_si(tmp2,tmp2,-1);acb_mul(tmp,a,a,prec);acb_mul(tmp,tmp,x,prec);acb_mul_2exp_si(tmp,tmp,-1);acb_mul_2exp_si(ax,ax,-1);acb_sinc(ax,ax,prec);acb_mul(ax,ax,ax,prec);acb_mul(tmp,tmp,ax,prec);acb_sub(tmp2,tmp2,tmp,prec);acb_mul_2exp_si(tmp2,tmp2,-1);acb_div(out,tmp2,den,prec);}
 acb_clear(L);acb_clear(pi);acb_clear(a);acb_clear(ax);acb_clear(ix);acb_clear(den);acb_clear(eh);acb_clear(emh);acb_clear(tmp);acb_clear(tmp2);acb_clear(one);acb_clear(two);return 0;}

static int integrate_real(arb_t out,enum kind kind,slong n,slong m,const arb_t L,const arb_t pi,slong prec){param_t p;p.kind=kind;p.n=n;p.m=m;arb_init(p.L);arb_init(p.pi);arb_set(p.L,L);arb_set(p.pi,pi);acb_t a,b,res;acb_init(a);acb_init(b);acb_init(res);acb_zero(a);setreal(b,L);mag_t tol;mag_init(tol);mag_set_ui_2exp_si(tol,1,-prec+16);acb_calc_integrate_opt_t opt;acb_calc_integrate_opt_init(opt);opt->depth_limit=20;opt->eval_limit=100000;int status=acb_calc_integrate(res,integrand,&p,a,b,prec/2,tol,opt,prec);arb_set(out,acb_realref(res));if(!arb_is_zero(acb_imagref(res)))status=1;mag_clear(tol);acb_clear(a);acb_clear(b);acb_clear(res);arb_clear(p.L);arb_clear(p.pi);return status;}

static int arch(arb_t out,slong n,slong m,const arb_t L,const arb_t pi,slong prec){arb_t x,y,w,eL,t;arb_init(x);arb_init(y);arb_init(w);arb_init(eL);arb_init(t);int status=0;if(n!=m){status|=integrate_real(x,ALPHA_INT,m,0,L,pi,prec);status|=integrate_real(y,ALPHA_INT,n,0,L,pi,prec);arb_sub(x,x,y,prec);/* alpha has 1/pi; integrals currently omit it */arb_div(x,x,pi,prec);arb_div_si(out,x,n-m,prec);}else{status|=integrate_real(x,GAMMA_INT,n,0,L,pi,prec);status|=integrate_real(y,BETA_INT,n,0,L,pi,prec);arb_div(y,y,L,prec);arb_const_euler(w,prec);arb_mul_ui(t,pi,4,prec);arb_log(t,t,prec);arb_add(w,w,t,prec);arb_mul_2exp_si(w,w,-1);arb_exp(eL,L,prec);arb_add_ui(t,eL,1,prec);arb_sub_ui(eL,eL,1,prec);arb_div(t,t,eL,prec);arb_log(t,t,prec);arb_mul_2exp_si(t,t,-1);arb_sub(w,w,t,prec);/* Correct gamma=integral+w; printed (4.14) adds c(L) twice. */arb_add(x,x,w,prec);arb_sub(x,x,y,prec);arb_mul_2exp_si(out,x,1);}arb_clear(x);arb_clear(y);arb_clear(w);arb_clear(eL);arb_clear(t);return status;}

static void qreal(arb_t out,slong n,slong m,const arb_t x,const arb_t L,const arb_t pi,slong prec){arb_t a,b,t;arb_init(a);arb_init(b);arb_init(t);if(n==m){arb_div(a,x,L,prec);arb_neg(a,a);arb_add_ui(a,a,1,prec);arb_mul(b,pi,x,prec);arb_mul_si(b,b,2*n,prec);arb_div(b,b,L,prec);arb_cos(b,b,prec);arb_mul(out,a,b,prec);arb_mul_2exp_si(out,out,1);}else{arb_mul(a,pi,x,prec);arb_mul_si(a,a,2*m,prec);arb_div(a,a,L,prec);arb_sin(a,a,prec);arb_mul(b,pi,x,prec);arb_mul_si(b,b,2*n,prec);arb_div(b,b,L,prec);arb_sin(b,b,prec);arb_sub(a,a,b,prec);arb_mul_si(t,pi,n-m,prec);arb_div(out,a,t,prec);}arb_clear(a);arb_clear(b);arb_clear(t);}
static void prime(arb_t out,slong n,slong m,ulong bound,const arb_t L,const arb_t pi,slong prec){arb_zero(out);arb_t x,q,l,t;arb_init(x);arb_init(q);arb_init(l);arb_init(t);for(ulong k=2;k<=bound;k++){ulong p;if(!ppbase(k,&p))continue;arb_log_ui(x,k,prec);qreal(q,n,m,x,L,pi,prec);arb_log_ui(l,p,prec);arb_mul(q,q,l,prec);arb_sqrt_ui(t,k,prec);arb_div(q,q,t,prec);arb_add(out,out,q,prec);}arb_clear(x);arb_clear(q);arb_clear(l);arb_clear(t);}

static int load_producer(arb_mat_t M,const char *path,slong N){FILE *f=fopen(path,"r");if(!f)return 0;char *line=NULL;size_t cap=0;ssize_t len;slong count=0;while((len=getline(&line,&cap,f))!=-1){if(strncmp(line,"DUMPQ ",6))continue;slong n,m;int pos=0;if(sscanf(line,"DUMPQ %ld %ld %n",&n,&m,&pos)!=2)continue;while(len>0&&(line[len-1]=='\n'||line[len-1]=='\r'))line[--len]='\0';if(n< -N||n>N||m< -N||m>N||arb_load_str(arb_mat_entry(M,n+N,m+N),line+pos)!=0){free(line);fclose(f);return 0;}count++;}free(line);fclose(f);return count==(2*N+1)*(2*N+1);}

int main(int argc,char **argv){const char *ls=NULL,*producer=NULL,*output=NULL;slong N=-1,prec=256;for(int i=1;i<argc;i++){if(!strcmp(argv[i],"--lambda")&&i+1<argc)ls=argv[++i];else if(!strcmp(argv[i],"--N")&&i+1<argc)N=atol(argv[++i]);else if(!strcmp(argv[i],"--prec")&&i+1<argc)prec=atol(argv[++i]);else if(!strcmp(argv[i],"--producer")&&i+1<argc)producer=argv[++i];else if(!strcmp(argv[i],"--output")&&i+1<argc)output=argv[++i];else return 2;}if(!ls||!producer||N<0||prec<64)return 2;if(output&&!freopen(output,"w",stdout))return 2;fmpq_t q,q2;fmpq_init(q);fmpq_init(q2);if(!parse_decimal(q,ls)||fmpq_cmp_ui(q,1)<=0)return 2;fmpq_mul(q2,q,q);fmpz_t bz;fmpz_init(bz);fmpz_fdiv_q(bz,fmpq_numref(q2),fmpq_denref(q2));if(!fmpz_abs_fits_ui(bz)||fmpz_sgn(bz)<0)return 2;ulong bound=fmpz_get_ui(bz);arb_t lam,L,pi;arb_init(lam);arb_init(L);arb_init(pi);arb_set_fmpq(lam,q,prec);arb_log(L,lam,prec);arb_mul_2exp_si(L,L,1);arb_const_pi(pi,prec);slong d=2*N+1;arb_mat_t P,A,R,Q,loaded;arb_mat_init(P,d,d);arb_mat_init(A,d,d);arb_mat_init(R,d,d);arb_mat_init(Q,d,d);arb_mat_init(loaded,d,d);int failed=!load_producer(loaded,producer,N);for(slong i=0;i<d;i++)for(slong j=0;j<d;j++){slong n=i-N,m=j-N;failed|=integrate_real(arb_mat_entry(P,i,j),POLE_DIRECT,n,m,L,pi,prec);failed|=arch(arb_mat_entry(A,i,j),n,m,L,pi,prec);prime(arb_mat_entry(R,i,j),n,m,bound,L,pi,prec);arb_sub(arb_mat_entry(Q,i,j),arb_mat_entry(P,i,j),arb_mat_entry(A,i,j),prec);arb_sub(arb_mat_entry(Q,i,j),arb_mat_entry(Q,i,j),arb_mat_entry(R,i,j),prec);if(!arb_is_finite(arb_mat_entry(Q,i,j))||arb_rel_accuracy_bits(arb_mat_entry(Q,i,j))<prec/2||!arb_overlaps(arb_mat_entry(Q,i,j),arb_mat_entry(loaded,i,j)))failed=1;}printf("META lambda=%s N=%ld prec=%ld cutoff=%lu path=direct_distribution_plus_corrected_4_14\n",ls,N,prec,bound);for(slong i=0;i<d;i++)for(slong j=0;j<d;j++){printf("ENTRY %ld %ld Q ",i-N,j-N);arb_printn(arb_mat_entry(Q,i,j),prec/3,ARB_STR_MORE);printf("\n");}printf("CHECK producer_verifier_entrywise_ball_overlap=%s\n",failed?"FAIL":"PASS");arb_mat_clear(P);arb_mat_clear(A);arb_mat_clear(R);arb_mat_clear(Q);arb_mat_clear(loaded);arb_clear(lam);arb_clear(L);arb_clear(pi);fmpq_clear(q);fmpq_clear(q2);fmpz_clear(bz);flint_cleanup();return failed?1:0;}
